156	fn fail_to_open_window(e: anyhow::Error, _cx: &mut App) {
157	    eprintln!(
158	        "Zed failed to open a window: {e:?}. See https://zed.dev/docs/linux for troubleshooting steps."
159	    );
160	    #[cfg(not(any(target_os = "linux", target_os = "freebsd")))]
161	    {
162	        process::exit(1);
163	    }
164	
165	    // Maybe unify this with gpui::platform::linux::platform::ResultExt::notify_err(..)?
166	    #[cfg(any(target_os = "linux", target_os = "freebsd"))]
167	    {
168	        use ashpd::desktop::notification::{Notification, NotificationProxy, Priority};
169	        _cx.spawn(async move |_cx| {
170	            let Ok(proxy) = NotificationProxy::new().await else {
171	                process::exit(1);
172	            };
173	
174	            let notification_id = "dev.zed.Oops";
175	            proxy
176	                .add_notification(
177	                    notification_id,
178	                    Notification::new("Zed failed to launch")
179	                        .body(Some(
180	                            format!(
181	                                "{e:?}. See https://zed.dev/docs/linux for troubleshooting steps."
182	                            )
183	                            .as_str(),
184	                        ))
185	                        .priority(Priority::High)
186	                        .icon(ashpd::desktop::Icon::with_names(&[
187	                            "dialog-question-symbolic",
188	                        ])),
189	                )
190	                .await
191	                .ok();
192	
193	            process::exit(1);
194	        })
195	        .detach();
196	    }
197	}
