1396	async fn installation_id(db: KeyValueStore) -> Result<IdType> {
1397	    let legacy_key_name = "device_id".to_string();
1398	    let key_name = "installation_id".to_string();
1399	
1400	    // Migrate legacy key to new key
1401	    if let Ok(Some(installation_id)) = db.read_kvp(&legacy_key_name) {
1402	        db.write_kvp(key_name, installation_id.clone()).await?;
1403	        db.delete_kvp(legacy_key_name).await?;
1404	        return Ok(IdType::Existing(installation_id));
1405	    }
1406	
1407	    if let Ok(Some(installation_id)) = db.read_kvp(&key_name) {
1408	        return Ok(IdType::Existing(installation_id));
1409	    }
1410	
1411	    let installation_id = Uuid::new_v4().to_string();
1412	
1413	    db.write_kvp(key_name, installation_id.clone()).await?;
1414	
1415	    Ok(IdType::New(installation_id))
1416	}
