1418	pub(crate) async fn restore_or_create_workspace(
1419	    app_state: Arc<AppState>,
1420	    cx: &mut AsyncApp,
1421	) -> Result<()> {
1422	    let kvp = cx.update(|cx| KeyValueStore::global(cx));
1423	    if let Some(multi_workspaces) = restorable_workspaces(cx, &app_state).await {
1424	        let mut error_count = 0;
1425	        for multi_workspace in multi_workspaces {
1426	            let result = match &multi_workspace.active_workspace.location {
1427	                SerializedWorkspaceLocation::Local => {
1428	                    restore_multiworkspace(multi_workspace, app_state.clone(), cx)
1429	                        .await
1430	                        .map(|_| ())
1431	                }
1432	                SerializedWorkspaceLocation::Remote(connection_options) => {
1433	                    let mut connection_options = connection_options.clone();
1434	                    if let RemoteConnectionOptions::Ssh(options) = &mut connection_options {
1435	                        cx.update(|cx| {
1436	                            RemoteSettings::get_global(cx)
1437	                                .fill_connection_options_from_settings(options)
1438	                        });
1439	                    }
1440	
1441	                    let paths = multi_workspace
1442	                        .active_workspace
1443	                        .paths
1444	                        .paths()
1445	                        .iter()
1446	                        .map(PathBuf::from)
1447	                        .collect::<Vec<_>>();
1448	                    let state = multi_workspace.state.clone();
1449	                    async {
1450	                        let window = open_remote_project(
1451	                            connection_options,
1452	                            paths,
1453	                            app_state.clone(),
1454	                            workspace::OpenOptions::default(),
1455	                            cx,
1456	                        )
1457	                        .await?;
1458	                        workspace::apply_restored_multiworkspace_state(
1459	                            window,
1460	                            &state,
1461	                            app_state.fs.clone(),
1462	                            cx,
1463	                        )
1464	                        .await;
1465	                        Ok::<(), anyhow::Error>(())
1466	                    }
1467	                    .await
1468	                }
1469	            };
1470	
1471	            if let Err(error) = result {
1472	                log::error!("Failed to restore workspace: {error:#}");
1473	                error_count += 1;
1474	            }
1475	        }
1476	
1477	        if error_count > 0 {
1478	            let message = if error_count == 1 {
1479	                "Failed to restore 1 workspace. Check logs for details.".to_string()
1480	            } else {
1481	                format!(
1482	                    "Failed to restore {} workspaces. Check logs for details.",
1483	                    error_count
1484	                )
1485	            };
1486	
1487	            // Try to find an active workspace to show the toast
1488	            let toast_shown = cx.update(|cx| {
1489	                if let Some(window) = cx.active_window()
1490	                    && let Some(multi_workspace) = window.downcast::<MultiWorkspace>()
1491	                {
1492	                    multi_workspace
1493	                        .update(cx, |multi_workspace, _, cx| {
1494	                            multi_workspace.workspace().update(cx, |workspace, cx| {
1495	                                workspace.show_toast(
1496	                                    Toast::new(NotificationId::unique::<()>(), message.clone()),
1497	                                    cx,
1498	                                )
1499	                            });
1500	                        })
1501	                        .ok();
1502	                    return true;
1503	                }
1504	                false
1505	            });
1506	
1507	            // If we couldn't show a toast (no windows opened successfully),
1508	            // open a fallback empty workspace and show the error there
1509	            if !toast_shown {
1510	                log::error!("All workspace restorations failed. Opening fallback empty workspace.");
1511	                cx.update(|cx| {
1512	                    workspace::open_new(
1513	                        Default::default(),
1514	                        app_state.clone(),
1515	                        cx,
1516	                        |workspace, _window, cx| {
1517	                            workspace.show_toast(
1518	                                Toast::new(NotificationId::unique::<()>(), message),
1519	                                cx,
1520	                            );
1521	                        },
1522	                    )
1523	                })
1524	                .await?;
1525	            }
1526	        }
1527	
1528	        // If the user cancelled a failed remote connection at startup,
1529	        // open_remote_project returns Ok but removes the window, so error_count
1530	        // stays 0 and the toast fallback above does not trigger. Without this
1531	        // check, Zed would exit silently.
1532	        if cx.update(|cx| cx.windows().is_empty()) {
1533	            cx.update(|cx| {
1534	                workspace::open_new(
1535	                    Default::default(),
1536	                    app_state.clone(),
1537	                    cx,
1538	                    |workspace, window, cx| {
1539	                        let restore_on_startup =
1540	                            WorkspaceSettings::get_global(cx).restore_on_startup;
1541	                        match restore_on_startup {
1542	                            workspace::RestoreOnStartupBehavior::Launchpad => {}
1543	                            _ => {
1544	                                Editor::new_file(workspace, &Default::default(), window, cx);
1545	                            }
1546	                        }
1547	                    },
1548	                )
1549	            })
1550	            .await?;
1551	        }
1552	    } else if matches!(kvp.read_kvp(FIRST_OPEN), Ok(None)) {
1553	        cx.update(|cx| show_onboarding_view(app_state, cx)).await?;
1554	    } else {
1555	        cx.update(|cx| {
1556	            workspace::open_new(
1557	                Default::default(),
1558	                app_state,
1559	                cx,
1560	                |workspace, window, cx| {
1561	                    let restore_on_startup = WorkspaceSettings::get_global(cx).restore_on_startup;
1562	                    match restore_on_startup {
1563	                        workspace::RestoreOnStartupBehavior::Launchpad => {}
1564	                        _ => {
1565	                            Editor::new_file(workspace, &Default::default(), window, cx);
1566	                        }
1567	                    }
1568	                },
1569	            )
1570	        })
1571	        .await?;
1572	    }
1573	
1574	    Ok(())
1575	}
