1585	pub(crate) async fn restorable_workspace_locations(
1586	    cx: &mut AsyncApp,
1587	    app_state: &Arc<AppState>,
1588	) -> Option<Vec<SessionWorkspace>> {
1589	    let (mut restore_behavior, db) = cx.update(|cx| {
1590	        (
1591	            WorkspaceSettings::get(None, cx).restore_on_startup,
1592	            workspace::WorkspaceDb::global(cx),
1593	        )
1594	    });
1595	
1596	    let session_handle = app_state.session.clone();
1597	    let (last_session_id, last_session_window_stack) = cx.update(|cx| {
1598	        let session = session_handle.read(cx);
1599	
1600	        (
1601	            session.last_session_id().map(|id| id.to_string()),
1602	            session.last_session_window_stack(),
1603	        )
1604	    });
1605	
1606	    if last_session_id.is_none()
1607	        && matches!(
1608	            restore_behavior,
1609	            workspace::RestoreOnStartupBehavior::LastSession
1610	        )
1611	    {
1612	        restore_behavior = workspace::RestoreOnStartupBehavior::LastWorkspace;
1613	    }
1614	
1615	    match restore_behavior {
1616	        workspace::RestoreOnStartupBehavior::LastWorkspace => {
1617	            workspace::last_opened_workspace_location(&db, app_state.fs.as_ref())
1618	                .await
1619	                .map(|(workspace_id, location, paths)| {
1620	                    vec![SessionWorkspace {
1621	                        workspace_id,
1622	                        location,
1623	                        paths,
1624	                        window_id: None,
1625	                    }]
1626	                })
1627	        }
1628	        workspace::RestoreOnStartupBehavior::LastSession => {
1629	            if let Some(last_session_id) = last_session_id {
1630	                let ordered = last_session_window_stack.is_some();
1631	
1632	                let mut locations = workspace::last_session_workspace_locations(
1633	                    &db,
1634	                    &last_session_id,
1635	                    last_session_window_stack,
1636	                    app_state.fs.as_ref(),
1637	                )
1638	                .await
1639	                .filter(|locations| !locations.is_empty());
1640	
1641	                // Since last_session_window_order returns the windows ordered front-to-back
1642	                // we need to open the window that was frontmost last.
1643	                if ordered && let Some(locations) = locations.as_mut() {
1644	                    locations.reverse();
1645	                }
1646	
1647	                locations
1648	            } else {
1649	                None
1650	            }
1651	        }
1652	        _ => None,
1653	    }
1654	}
